mapper.update:
UPDATE ORDERS
SET ORDER_STATUS = #{orderStatus}
WHERE ORDER_ID = #{orderId}

mapper.delete:
DELETE FROM CART
WHERE USER_ID = #{userId}
AND FIND_IN_SET(
CART_ID,
(SELECT CART_IDS FROM ORDERS WHERE ORDER_ID = #{orderId})
) > 0
AND CART_TYPE = (
SELECT ORDER_TYPE
FROM ORDERS
WHERE ORDER_ID = #{orderId}
)

mapper.insert:
INSERT INTO POINT_HISTORY (
USER_ID, DESCRIPTION, AMOUNT, TYPE, CREATED_AT, BALANCE_AFTER
) VALUES (
#{userId},
#{description},
#{earnedPoint},
'EARN',
NOW(),
(
SELECT COALESCE(POINT, 0) + #{earnedPoint}
FROM USER
WHERE USER_ID = #{userId}
)
)

mapper.update:
UPDATE USER
SET POINT = POINT + #{earnedPoint} - #{usePoint},
TOTAL_AMOUNT = TOTAL_AMOUNT + #{amount}
WHERE USER_ID = #{userId}

UPDATE product_stock
SET AVAILABLE_QTY = AVAILABLE_QTY - #{quantity}
WHERE PRODUCT_ID = #{productId}
AND OPTION_ITEM_ID = #{optionItemId}
AND STOCK_DATE IS NULL
AND AVAILABLE_QTY >= #{quantity}

 UPDATE
		product_stock SET RESERVED_QTY = RESERVED_QTY + #{quantity},
		AVAILABLE_QTY = AVAILABLE_QTY - #{quantity} WHERE PRODUCT_ID =
		#{productId}
		AND OPTION_ITEM_ID = #{optionItemId}
		AND STOCK_DATE
		BETWEEN #{startDate} AND DATE_SUB(#{endDate}, INTERVAL 1 DAY) AND
		AVAILABLE_QTY >= #{quantity}

UPDATE product_stock
SET AVAILABLE_QTY = AVAILABLE_QTY + #{quantity}
WHERE PRODUCT_ID = #{productId}
AND OPTION_ITEM_ID = #{optionItemId}
AND STOCK_DATE IS NULL

mapper.select:
SELECT *
FROM USER_COUPON uc
WHERE uc.USER_COUPON_ID = #{userCouponId}
AND uc.USER_ID = #{userId}
AND uc.STATUS = 'AVAILABLE'
AND NOT EXISTS (
SELECT 1
FROM COUPON_USE_LOG cul
WHERE cul.USER_COUPON_ID = uc.USER_COUPON_ID
)
